python3 - <<'EOF'
import re
for f,step,cls in [("people.POST.yml","create","person.RecordPersonAdded"),
                   ("people/{personId}.PUT.yml","save","person.RecordPersonEdited"),
                   ("people/{personId}/claims.POST.yml","create","claim.RecordClaimAdded"),
                   ("claims/{claimId}.PUT.yml","save","claim.RecordClaimEdited")]:
    s=open(f).read()
    pat=re.compile(r"(^%s:\n(?:  .*\n)*?)  next: respond\n"%step, re.M)
    s,n=pat.subn(lambda m:m.group(1)+"  next: audit\naudit:\n  class: net.officefloor.hq.app.%s\n  govern: [ transaction ]\n  next: respond\n"%cls, s)
    assert n==1,f
    open(f,"w").write(s)
EOF
